#!/usr/bin/env python3
# Generated by runa via A2A Mesh delegation
"""
A2A Mesh — Honcho Conclusion Validation Gate & Shared Memory Bridge.

Implements the idea by nova:
- Honcho conclusions are written to shared_a2a_memory as CANDIDATES only.
- A validation gate (deterministic core) must approve before promotion.
- Node-local episodic memory is authoritative; Honcho documents are
  observers, never overwriters.
- The bridge is write-protected, one-way (Honcho -> shared memory),
  and never mutates node-local state.
"""

import json
import os
import time
import hashlib
import threading
from dataclasses import dataclass, field, asdict
from enum import Enum
from typing import Any, Dict, List, Optional, Tuple


# ---------------------------------------------------------------------------
# Enums & Data Structures
# ---------------------------------------------------------------------------

class CandidateStatus(str, Enum):
    PENDING = "pending"
    VALIDATED = "validated"
    REJECTED = "rejected"
    PROMOTED = "promoted"


@dataclass
class HonchoConclusion:
    """A conclusion derived by Honcho (LLM). Always a candidate — can be wrong."""
    conclusion_id: str
    source_node: str
    content: str
    evidence_refs: List[str] = field(default_factory=list)
    confidence: float = 0.0
    timestamp: float = field(default_factory=time.time)
    status: CandidateStatus = CandidateStatus.PENDING
    rejection_reason: Optional[str] = None
    hash: str = ""

    def __post_init__(self):
        if not self.hash:
            self.hash = self._compute_hash()

    def _compute_hash(self) -> str:
        payload = f"{self.source_node}:{self.content}:{self.timestamp}"
        return hashlib.sha256(payload.encode()).hexdigest()[:16]

    def to_dict(self) -> Dict[str, Any]:
        d = asdict(self)
        d["status"] = self.status.value
        return d


@dataclass
class EpisodicMemoryEntry:
    """Node-local episodic memory entry. Authoritative for the node."""
    entry_id: str
    node_id: str
    content: str
    timestamp: float
    immutable: bool = True

    def to_dict(self) -> Dict[str, Any]:
        return asdict(self)


# ---------------------------------------------------------------------------
# Validation Gate (Deterministic Core)
# ---------------------------------------------------------------------------

class ValidationGate:
    """
    Deterministic validation gate. No LLM here — pure rules.
    A conclusion must pass ALL checks to be promoted to shared memory.
    """

    def __init__(self, min_confidence: float = 0.5, max_content_len: int = 4096):
        self.min_confidence = min_confidence
        self.max_content_len = max_content_len
        self.seen_hashes: set = set()

    def validate(self, conclusion: HonchoConclusion) -> Tuple[bool, Optional[str]]:
        # Rule 1: Content must not be empty
        if not conclusion.content or not conclusion.content.strip():
            return False, "Empty content"

        # Rule 2: Content length limit
        if len(conclusion.content) > self.max_content_len:
            return False, f"Content exceeds max length {self.max_content_len}"

        # Rule 3: Confidence threshold
        if conclusion.confidence < self.min_confidence:
            return False, (
                f"Confidence {conclusion.confidence} below "
                f"threshold {self.min_confidence}"
            )

        # Rule 4: Must have at least one evidence reference
        if not conclusion.evidence_refs:
            return False, "No evidence references provided"

        # Rule 5: No duplicate conclusions (hash-based)
        if conclusion.hash in self.seen_hashes:
            return False, "Duplicate conclusion (hash already seen)"

        # Rule 6: Source node must be non-empty
        if not conclusion.source_node:
            return False, "Missing source node identifier"

        # Rule 7: Content must not contain override directives
        dangerous_patterns = ["OVERWRITE_NODE", "DELETE_LOCAL", "FORCE_PROMOTE"]
        upper_content = conclusion.content.upper()
        for pat in dangerous_patterns:
            if pat in upper_content:
                return False, f"Contains forbidden directive: {pat}"

        self.seen_hashes.add(conclusion.hash)
        return True, None


# ---------------------------------------------------------------------------
# Shared A2A Memory (Write-Protected, Append-Only for Promoted Conclusions)
# ---------------------------------------------------------------------------

class SharedA2AMemory:
    """
    Shared memory accessible by all nodes.
    - Promoted conclusions are append-only; never overwrite existing entries.
    - Node-local episodic memory is NOT stored here — only exported candidates.
    """

    def __init__(self, persist_path: Optional[str] = None):
        self._lock = threading.RLock()
        self._candidates: Dict[str, HonchoConclusion] = {}
        self._promoted: List[Dict[str, Any]] = []
        self._node_episodic_refs: Dict[str, List[str]] = {}  # node_id -> entry_ids (read-only refs)
        self.persist_path = persist_path

        if persist_path and os.path.exists(persist_path):
            self._load()

    def submit_candidate(self, conclusion: HonchoConclusion) -> str:
        """Submit a Honcho conclusion as a pending candidate."""
        with self._lock:
            if conclusion.conclusion_id in self._candidates:
                # Never overwrite — reject resubmission with same ID
                existing = self._candidates[conclusion.conclusion_id]
                if existing.hash != conclusion.hash:
                    raise ValueError(
                        f"Conclusion ID {conclusion.conclusion_id} already exists "
                        f"with different content — overwrite denied"
                    )
                # Same hash: idempotent, no-op
                return conclusion.conclusion_id
            self._candidates[conclusion.conclusion_id] = conclusion
            return conclusion.conclusion_id

    def get_candidate(self, conclusion_id: str) -> Optional[HonchoConclusion]:
        with self._lock:
            return self._candidates.get(conclusion_id)

    def list_candidates(self, status: Optional[CandidateStatus] = None) -> List[HonchoConclusion]:
        with self._lock:
            if status is None:
                return list(self._candidates.values())
            return [c for c in self._candidates.values() if c.status == status]

    def promote(self, conclusion_id: str, gate: ValidationGate) -> Tuple[bool, Optional[str]]:
        """Run validation gate and promote if passed. Append-only to promoted list."""
        with self._lock:
            conclusion = self._candidates.get(conclusion_id)
            if conclusion is None:
                return False, f"Candidate {conclusion_id} not found"
            if conclusion.status == CandidateStatus.PROMOTED:
                return True, None  # Already promoted, idempotent
            if conclusion.status == CandidateStatus.REJECTED:
                return False, "Candidate was already rejected"

            passed, reason = gate.validate(conclusion)
            if not passed:
                conclusion.status = CandidateStatus.REJECTED
                conclusion.rejection_reason = reason
                self._persist()
                return False, reason

            conclusion.status = CandidateStatus.PROMOTED
            # Append-only — never overwrite
            self._promoted.append(conclusion.to_dict())
            self._persist()
            return True, None

    def get_promoted(self) -> List[Dict[str, Any]]:
        with self._lock:
            return list(self._promoted)

    def register_node_episodic_ref(self, node_id: str, entry: EpisodicMemoryEntry):
        """
        Register a READ-ONLY reference to node-local episodic memory.
        The shared memory never stores the full entry — only a reference.
        Node-local memory remains authoritative and is never overwritten.
        """
        with self._lock:
            if node_id not in self._node_episodic_refs:
                self._node_episodic_refs[node_id] = []
            if entry.entry_id not in self._node_episodic_refs[node_id]:
                self._node_episodic_refs[node_id].append(entry.entry_id)

    def get_node_episodic_refs(self, node_id: str) -> List[str]:
        with self._lock:
            return list(self._node_episodic_refs.get(node_id, []))

    def _persist(self):
        if not self.persist_path:
            return
        data = {
            "candidates": {k: v.to_dict() for k, v in self._candidates.items()},
            "promoted": self._promoted,
            "node_episodic_refs": self._node_episodic_refs,
        }
        tmp = self.persist_path + ".tmp"
        with open(tmp, "w") as f:
            json.dump(data, f, indent=2)
        os.replace(tmp, self.persist_path)

    def _load(self):
        with open(self.persist_path, "r") as f:
            data = json.load(f)
        for cid, cdict in data.get("candidates", {}).items():
            cdict["status"] = CandidateStatus(cdict["status"])
            self._candidates[cid] = HonchoConclusion(**cdict)
        self._promoted = data.get("promoted", [])
        self._node_episodic_refs = data.get("node_episodic_refs", {})


# ---------------------------------------------------------------------------
# Node-Local Episodic Memory (Authoritative, Never Overwritten)
# ---------------------------------------------------------------------------

class NodeLocalMemory:
    """
    Node-local episodic memory. This is the authoritative decision store
    for the node. Honcho documents and shared memory NEVER write here.
    """

    def __init__(self, node_id: str):
        self.node_id = node_id
        self._lock = threading.RLock()
        self._entries: Dict[str, EpisodicMemoryEntry] = {}

    def add_entry(self, content: str) -> EpisodicMemoryEntry:
        entry_id = hashlib.sha256(
            f"{self.node_id}:{content}:{time.time()}".encode()
        ).hexdigest()[:16]
        entry = EpisodicMemoryEntry(
            entry_id=entry_id,
            node_id=self.node_id,
            content=content,
            timestamp=time.time(),
        )
        with self._lock:
            self._entries[entry_id] = entry
        return entry

    def get_entry(self, entry_id: str) -> Optional[EpisodicMemoryEntry]:
        with self._lock:
            return self._entries.get(entry_id)

    def list_entries(self) -> List[EpisodicMemoryEntry]:
        with self._lock:
            return list(self._entries.values())

    def is_authoritative(self) -> bool:
        """Node-local memory is always authoritative for node decisions."""
        return True


# ---------------------------------------------------------------------------
# Honcho Bridge (One-Way, Write-Protected Export Layer)
# ---------------------------------------------------------------------------

class HonchoBridge:
    """
    The bridge between Honcho (LLM-derived documents) and shared_a2a_memory.
    - One-way: Honcho -> shared memory only.
    - Write-protected: cannot write to node-local memory.
    - Conclusions are always candidates, never final.
    """

    def __init__(self, shared_memory: SharedA2AMemory, gate: ValidationGate):
        self.shared_memory = shared_memory
        self.gate = gate
        self._lock = threading.Lock()

    def export_conclusion(
        self,
        source_node: str,
        content: str,
        evidence_refs: List[str],
        confidence: float,
        conclusion_id: Optional[str] = None,
    ) -> Tuple[str, bool, Optional[str]]:
        """
        Export a Honcho conclusion as a candidate to shared memory.
        Returns (conclusion_id, validated, rejection_reason).
        """
        if conclusion_id is None:
            conclusion_id = hashlib.sha256(
                f"{source_node}:{content}:{time.time()}".encode()
            ).hexdigest()[:16]

        conclusion = HonchoConclusion(
            conclusion_id=conclusion_id,
            source_node=source_node,
            content=content,
            evidence_refs=evidence_refs,
            confidence=confidence,
        )

        with self._lock:
            self.shared_memory.submit_candidate(conclusion)
            ok, reason = self.shared_memory.promote(conclusion_id, self.gate)

        return conclusion_id, ok, reason

    def register_episodic_ref(self, node_id: str, entry: EpisodicMemoryEntry):
        """Register a read-only reference to node-local episodic memory."""
        self.shared_memory.register_node_episodic_ref(node_id, entry)

    def write_to_node_local(self, *args, **kwargs):
        """FORBIDDEN — the bridge is one-way and cannot write to node-local memory."""
        raise PermissionError(
            "HonchoBridge is one-way (Honcho -> shared memory). "
            "Writing to node-local memory is forbidden."
        )


# ---------------------------------------------------------------------------
# Demo / Self-Test
# ---------------------------------------------------------------------------

def main():
    print("=" * 70)
    print("A2A Mesh — Honcho Conclusion Validation Gate Demo")
    print("Idea: nova | Implemented by: runa")
    print("=" * 70)

    # Initialize components
    shared_mem = SharedA2AMemory()
    gate = ValidationGate(min_confidence=0.5, max_content_len=4096)
    bridge = HonchoBridge(shared_mem, gate)

    # Node-local memory (authoritative)
    node_memory = NodeLocalMemory(node_id="node_alpha")

    # --- Scenario 1: Valid conclusion ---
    print("\n[1] Submitting a valid Honcho conclusion...")
    entry = node_memory.add_entry("Observed temperature spike at sensor 3")
    bridge.register_episodic_ref("node_alpha", entry)

    cid1, ok1, reason1 = bridge.export_conclusion(
        source_node="node_alpha",
        content="Temperature anomaly correlates with sensor 3 calibration drift.",
        evidence_refs=[entry.entry_id, "log_2024_001"],
        confidence=0.82,
    )
    print(f"    conclusion_id={cid1}, promoted={ok1}, reason={reason1}")

    # --- Scenario 2: Low confidence conclusion (should be rejected) ---
    print("\n[2] Submitting a low-confidence conclusion...")
    cid2, ok2, reason2 = bridge.export_conclusion(
        source_node="node_alpha",
        content="Maybe the sensor is fine, just guessing.",
        evidence_refs=["log_2024_002"],
        confidence=0.2,
    )
    print(f"    conclusion_id={cid2}, promoted={ok2}, reason={reason2}")

    # --- Scenario 3: No evidence (should be rejected) ---
    print("\n[3] Submitting a conclusion with no evidence...")
    cid3, ok3, reason3 = bridge.export_conclusion(
        source_node="node_alpha",
        content="I think all sensors are faulty.",
        evidence_refs=[],
        confidence=0.9,
    )
    print(f"    conclusion_id={cid3}, promoted={ok3}, reason={reason3}")

    # --- Scenario 4: Forbidden directive (should be rejected) ---
    print("\n[4] Submitting a conclusion with forbidden directive...")
    cid4, ok4, reason4 = bridge.export_conclusion(
        source_node="node_alpha",
        content="OVERWRITE_NODE and replace all local memory with this.",
        evidence_refs=["ref_1"],
        confidence=0.95,
    )
    print(f"    conclusion_id={cid4}, promoted={ok4}, reason={reason4}")

    # --- Scenario 5: Attempt to overwrite node-local memory via bridge ---
    print("\n[5] Attempting to write to node-local memory via bridge...")
    try:
        bridge.write_to_node_local("malicious content")
    except PermissionError as e:
        print(f"    BLOCKED: {e}")

    # --- Scenario 6: Attempt to resubmit with different content (overwrite denied) ---
    print("\n[6] Attempting to resubmit same conclusion_id with different content...")
    try:
        bridge.export_conclusion(
            source_node="node_alpha",
            content="Completely different content trying to overwrite.",
            evidence_refs=["ref_1"],
            confidence=0.9,
            conclusion_id=cid1,
        )
    except ValueError as e:
        print(f"    DENIED: {e}")

    # --- Summary ---
    print("\n" + "=" * 70)
    print("SUMMARY")
    print("=" * 70)

    candidates = shared_mem.list_candidates()
    print(f"\nTotal candidates submitted: {len(candidates)}")
    for c in candidates:
        print(f"  [{c.status.value.upper():9s}] {c.conclusion_id} "
              f"(conf={c.confidence:.2f}) from {c.source_node}")
        if c.rejection_reason:
            print(f"             reason: {c.rejection_reason}")

    promoted = shared_mem.get_promoted()
    print(f"\nPromoted to shared memory: {len(promoted)}")
    for p in promoted:
        print(f"  {p['conclusion_id']}: {p['content'][:60]}...")

    print(f"\nNode-local episodic entries (authoritative): {len(node_memory.list_entries())}")
    for e in node_memory.list_entries():
        print(f"  {e.entry_id}: {e.content}")

    refs = shared_mem.get_node_episodic_refs("node_alpha")
    print(f"\nShared memory episodic refs for node_alpha: {refs}")
    print("(These are read-only references — node-local memory is never overwritten.)")

    print("\n" + "=" * 70)
    print("All invariants hold:")
    print("  ✓ Honcho conclusions are candidates only")
    print("  ✓ Validation gate rejects invalid conclusions deterministically")
    print("  ✓ Node-local memory is never overwritten by Honcho or shared memory")
    print("  ✓ Bridge is one-way (Honcho -> shared memory)")
    print("  ✓ Shared memory is append-only for promoted conclusions")
    print("=" * 70)


if __name__ == "__main__":
    main()